int main() {
    int n;
    cin >> n;

    vector<int> dp(n + 1);
    dp[0] = 1;

    for (int i = 1; i <= n; ++i) {
        if (i & 1) {
            dp[i] = 0;
        } else {
            dp[i] = dp[i - 2] * 2;
        }
    }

    cout << dp[n];
    return 0;
}

